<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {request} from '@/api/client'
import {uiText,uiLocale} from '@/i18n'
import {createRequestGuard} from '@/lib/requestGuard'
interface Snapshot {checkedAt:string;requests:number;errors:number;averageMs:number;p95Ms:number;freeBytes:number;totalBytes:number;failedJobs:number;alerts:{id:string;severity:string;title:string;action:string;url:string}[]}
const data=ref<Snapshot>(),error=ref(''),busy=ref(false),guard=createRequestGuard()
let timer:ReturnType<typeof setTimeout>,active=true
async function load(){const run=guard.start();busy.value=true;try{const value=await request<Snapshot>('/operations',{signal:run.signal});if(run.current()){data.value=value;error.value=''}}catch(e){if(run.current())error.value=(e as Error).message}finally{if(run.current())busy.value=false}}
function poll(){timer=setTimeout(async()=>{if(!document.hidden)await load();if(active)poll()},30000)}
onMounted(()=>{void load();poll()});onBeforeUnmount(()=>{active=false;guard.cancel();clearTimeout(timer)})
</script>
<template><section class="operations-panel panel"><header><div><p class="page-kicker">SYSTEM HEALTH</p><h3>{{uiText('运行与提醒')}}</h3><p class="research-hint">{{uiText('最近五分钟的普通 API 请求；实时流不计入延迟。')}}</p></div><button class="button button--ghost" :disabled="busy" @click="load">{{uiText('刷新')}}</button></header><p v-if="error" role="alert">{{uiText(error)}}</p><template v-if="data"><div class="operations-metrics"><div><span>{{uiText('请求次数')}}</span><strong>{{data.requests}}</strong></div><div><span>{{uiText('服务错误')}}</span><strong>{{data.errors}}</strong></div><div><span>{{uiText('平均响应')}}</span><strong>{{Math.round(data.averageMs)}} ms</strong></div><div><span>{{uiText('P95 延迟上界')}}</span><strong>{{data.requests?(data.p95Ms<0?'> 5000':data.p95Ms)+' ms':'—'}}</strong></div><div><span>{{uiText('服务所在磁盘可用')}}</span><strong>{{data.freeBytes<0?'—':(data.freeBytes/1073741824).toFixed(1)+' GB'}}</strong></div></div><p class="research-hint">{{uiText('磁盘读数仅代表当前服务所在文件系统，不包含其他主机或独立存储卷。')}}</p><article v-for="a in data.alerts" :key="a.id" class="operation-alert" :class="a.severity"><div><strong>{{uiText(a.title)}}</strong><p>{{uiText(a.action)}}</p></div><RouterLink :to="a.url">{{uiText('查看 →')}}</RouterLink></article><p v-if="!data.alerts.length">{{uiText('当前没有需要处理的运行提醒。')}}</p><small>{{uiText('更新于')}} {{new Date(data.checkedAt).toLocaleTimeString(uiLocale())}}</small></template></section></template>
<style scoped>.operations-panel{padding:28px}.operations-panel header,.operation-alert{display:flex;justify-content:space-between;align-items:center;gap:20px}.operations-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:20px;padding:24px 0}.operations-metrics span{display:block;color:var(--muted);font-size:12px}.operations-metrics strong{display:block;font-size:22px;font-weight:500;margin-top:10px}.operation-alert{padding:18px 0;border-top:1px solid var(--line)}.operation-alert p{font-size:13px;color:var(--muted);margin:6px 0}.operation-alert a{flex-shrink:0}.operation-alert.danger strong{color:var(--danger,#aa4650)}small{color:var(--muted)}@media(max-width:800px){.operations-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
